export class Board {
    constructor(width, height, tileTypes) {
        this.width = width;
        this.height = height;
        this.tileTypes = tileTypes;
        this.grid = [];
        for (let r = 0; r < height; r++) {
            const row = [];
            for (let c = 0; c < width; c++) {
                row.push(null);
            }
            this.grid.push(row);
        }
    }

    getTile(row, col) {
        if (row < 0 || row >= this.height || col < 0 || col >= this.width) return null;
        return this.grid[row][col];
    }

    remove(row, col) {
        if (this.grid[row] && this.grid[row][col]) {
            this.grid[row][col] = null;
        }
    }

    isCleared() {
        for (let r = 0; r < this.height; r++) {
            for (let c = 0; c < this.width; c++) {
                if (this.grid[r][c] !== null) return false;
            }
        }
        return true;
    }
}

export class PathFinder {
    static findPath(board, start, end) {
        // Basic direct-line check for the stub; full algorithm to be implemented.
        const t1 = board.getTile(start.row, start.col);
        const t2 = board.getTile(end.row, end.col);
        if (!t1 || !t2 || t1.type !== t2.type) return null;

        if (start.row === end.row) {
            let minC = Math.min(start.col, end.col);
            let maxC = Math.max(start.col, end.col);
            for (let c = minC + 1; c < maxC; c++) {
                if (board.getTile(start.row, c) !== null) return null;
            }
            return [{row: start.row, col: start.col}, {row: end.row, col: end.col}];
        } else if (start.col === end.col) {
            let minR = Math.min(start.row, end.row);
            let maxR = Math.max(start.row, end.row);
            for (let r = minR + 1; r < maxR; r++) {
                if (board.getTile(r, start.col) !== null) return null;
            }
            return [{row: start.row, col: start.col}, {row: end.row, col: end.col}];
        }
        // TODO: implement full 0/1/2-bend pathfinding
        return null;
    }
}

export function createBoardSvg(board, svgElement) {
    svgElement.innerHTML = '';
    const cellSize = 60;
    for (let r = 0; r < board.height; r++) {
        for (let c = 0; c < board.width; c++) {
            const tile = board.getTile(r, c);
            const x = c * cellSize;
            const y = r * cellSize;
            if (tile) {
                const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                rect.setAttribute('x', x);
                rect.setAttribute('y', y);
                rect.setAttribute('width', cellSize);
                rect.setAttribute('height', cellSize);
                rect.setAttribute('class', `tile tile-type-${tile.type}`);
                rect.setAttribute('id', `tile-${r}-${c}`);
                svgElement.appendChild(rect);
            }
        }
    }
}

export function animatePath(path, svgElement, callback) {
    const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    const points = path.map(p => `${p.col * 60 + 30},${p.row * 60 + 30}`).join(' ');
    polyline.setAttribute('points', points);
    polyline.setAttribute('fill', 'none');
    polyline.setAttribute('stroke', 'gold');
    polyline.setAttribute('stroke-width', 4);
    polyline.setAttribute('id', 'connection-path');
    svgElement.appendChild(polyline);
    setTimeout(() => {
        svgElement.removeChild(polyline);
        callback();
    }, 800);
}

export function removeTile(row, col, svgElement, callback) {
    const tileEl = svgElement.querySelector(`#tile-${row}-${col}`);
    if (tileEl) {
        tileEl.setAttribute('opacity', 0);
        setTimeout(() => {
            tileEl.remove();
            callback();
        }, 400);
    } else {
        callback();
    }
}

export function drawScore(score, containerElement) {
    containerElement.textContent = `Score: ${score}`;
}

import { Board, PathFinder } from './game.js';
import { createBoardSvg, animatePath, removeTile, drawScore } from './renderer.js';

let board;
let selected = null;
let score = 0;

export function initGame(svgElement, scoreElement) {
    board = new Board(10, 8, 4);
    // Randomly populate the board for the stub; real implementation may shuffle properly.
    for (let r = 0; r < board.height; r++) {
        for (let c = 0; c < board.width; c++) {
            const type = Math.floor(Math.random() * 4) + 1;
            board.grid[r][c] = { row: r, col: c, type };
        }
    }
    createBoardSvg(board, svgElement);
    drawScore(score, scoreElement);
    svgElement.addEventListener('click', (event) => handleClick(event, svgElement, scoreElement));
}

export function getBoard() {
    return board;
}

function handleClick(event, svgElement, scoreElement) {
    const target = event.target;
    if (!target || !target.id.startsWith('tile-')) return;
    const parts = target.id.split('-');
    const row = parseInt(parts[1]);
    const col = parseInt(parts[2]);
    const tile = board.getTile(row, col);
    if (!tile) return;

    if (selected) {
        if (selected.row === row && selected.col === col) {
            target.classList.remove('tile-selected');
            selected = null;
            return;
        }
        const path = PathFinder.findPath(board, selected, tile);
        if (path) {
            animatePath(path, svgElement, () => {
                removeTile(selected.row, selected.col, svgElement, () => {
                    board.remove(selected.row, selected.col);
                    removeTile(row, col, svgElement, () => {
                        board.remove(row, col);
                        score += 10;
                        drawScore(score, scoreElement);
                        if (board.isCleared()) {
                            alert('Congratulations! You cleared the board!');
                        }
                    });
                });
            });
            selected = null;
        } else {
            const oldEl = svgElement.querySelector(`#tile-${selected.row}-${selected.col}`);
            if (oldEl) oldEl.classList.remove('tile-selected');
            target.classList.add('tile-selected');
            setTimeout(() => target.classList.remove('tile-selected'), 300);
            selected = null;
        }
    } else {
        target.classList.add('tile-selected');
        selected = { row, col };
    }
}

import { initGame } from './ui.js';

document.addEventListener('DOMContentLoaded', () => {
    const svg = document.getElementById('game-board');
    const score = document.getElementById('score');
    initGame(svg, score);
});
